package com.reviewflow.web;
import com.reviewflow.domain.*; import com.reviewflow.repo.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI;
@RestController public class PublicRedirectController { private final BusinessRepository businesses; private final QrCodeRepository codes; private final QrScanRepository scans; public PublicRedirectController(BusinessRepository b,QrCodeRepository c,QrScanRepository s){businesses=b;codes=c;scans=s;}
 @GetMapping("/r/{slug}") public ResponseEntity<Void> redirect(@PathVariable String slug,HttpServletRequest req){ Business b=businesses.findBySlug(slug).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND)); QrCode q=codes.findByTrackingSlugAndActiveTrue(slug).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.GONE)); QrScan scan=new QrScan();scan.qrCodeId=q.id;scan.deviceType=device(req.getHeader("User-Agent"));scan.browser=browser(req.getHeader("User-Agent"));scans.save(scan);return ResponseEntity.status(HttpStatus.FOUND).location(URI.create(b.googleReviewUrl)).build(); }
 private String device(String ua){return ua!=null&&ua.toLowerCase().contains("mobile")?"mobile":"desktop";} private String browser(String ua){if(ua==null)return "unknown";if(ua.contains("Chrome"))return "Chrome";if(ua.contains("Safari"))return "Safari";return "other";} }
